+// The SDK must honor the same outer context used by the live suite. Actual
+// daemon calls are substituted by a local HTTP peer that stalls until cancel.
+func TestT210DockerAPIBounds(t *testing.T) {
+	for _, name := range []string{"Ping", "List", "Inspect"} {
+		t.Run(name, func(t *testing.T) {
+			done := make(chan struct{})
+			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+				if r.URL.Path == "/_ping" && name != "Ping" {
+					w.Header().Set("API-Version", "1.51")
+					w.WriteHeader(200)
+					return
+				}
+				select {
+				case <-r.Context().Done():
+				case <-done:
+				}
+			}))
+			defer server.Close()
+			defer close(done)
+			cli, err := client.NewClientWithOpts(client.WithHost(server.URL), client.WithVersion("1.51"))
+			if err != nil {
+				t.Fatal(err)
+			}
+			defer cli.Close()
+			ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
+			defer cancel()
+			start := time.Now()
+			switch name {
+			case "Ping":
+				_, err = cli.Ping(ctx)
+			case "List":
